WITH eligible AS (SELECT s.* FROM sessions s WHERE NOT EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_time >= s.started_at)) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, MAX(started_at) AS ended_at, MIN(started_at) AS first_seen, SIZE(COLLECT_SET(country)) AS num_countries FROM eligible GROUP BY DATE_TRUNC('QUARTER', started_at) ORDER BY quarter_start DESC NULLS LAST
